"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["92440"],{60182(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.fase_referenciada_por_formulario","status":422,"titulo":"A fase \xe9 usada por um formul\xe1rio e n\xe3o pode sair do cronograma"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.fase_referenciada_por_formulario","requisitos":["UNI-REQ-0144"],"oQueAconteceu":["O novo cronograma deixa de incluir uma fase na qual um formul\xe1rio do processo \xe9\\nrespondido. O formul\xe1rio fica ligado a uma fase do cronograma e abre e fecha com o prazo\\ndela; sem a fase, ele ficaria sem onde ser respondido. A mensagem de detalhe cita a fase\\n(com o c\xf3digo e a ordem) e a finalidade do formul\xe1rio. A recusa sai com **422** e o\\ncronograma anterior permanece.","Se a fase removida tamb\xe9m sustenta outras coisas, a recusa vem primeiro pela que o\\nsistema confere antes: a idade m\xe1xima de emiss\xe3o de documento exigido em outra fase e a\\netapa citada por crit\xe9rio de desempate ou regra de elimina\xe7\xe3o. Este c\xf3digo aparece\\nquando resta o formul\xe1rio."],"comoResolver":["Escolha entre manter a fase ou mudar o formul\xe1rio:","- mantenha a fase no cronograma enviado; ou\\n- troque a fase do formul\xe1rio por outra que continue no cronograma\\n  (`PUT /api/selecao/admin/processos-seletivos/{id}/formularios/{finalidade}`) e repita\\n  a defini\xe7\xe3o do cronograma\\n  (`PUT /api/selecao/processos-seletivos/{id}/cronograma-fases`)."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);